test('L. predecessor-generated version-1 annotation/pending records replay byte-identical under their own contract, are never promoted to sealed truth, and unverifiable legacy links are retained but never applied', async () => {
  assert.equal(REC.producedBy, '32434e81d066099b656f7abf1d66dadb3df95481');
  for (const [name, sc] of Object.entries(REC.scenarios)) {
    const rp = replaySocialHistory(sc.history); assert.equal(rp.ok, true, `${name}: ${rp.error}`); assert.equal(rp.recordVersions.annotations[2] + rp.recordVersions.pending[2], 0, `${name}: legacy records are version 1`); assert.equal(rp.pendingUnlinked.length, 0, `${name}: genuine legacy links hold`);
    // every legacy record survives the candidate's own redelivery of the same inputs byte-identically, with no duplicate representation
    const p = name === 'fc_recast' ? 'fc' : 'bsky'; const before = sc.history.map((e) => canonicalJson(e));
    for (const step of sc.steps) { const r = await pipeline({ p, arr: structuredClone(sc.history), deliveries: step.deliveries, nowMs: step.nowMs + 5_000 }); assert.equal(src(r.appended).length + ann(r.appended).length + pend(r.appended).length, 0, `${name}: redelivery repeats nothing`); for (let i = 0; i < before.length; i++) assert.equal(canonicalJson(r.arr[i]), before[i]); }
  }
  // the legacy conflict applies under its own contract — labelled UNSEALED, no seal manufactured
  const conflict = REC.scenarios.conflict; const cp = replaySocialHistory(conflict.history); const target = src(conflict.history)[0]; const id = target.sourceEventId;
  const v = socialTemporalView({ event: target, annotations: cp.annotations.get(id), pending: cp.pendingByTarget.get(id), asOfTs: REC.T2, settledOrder: cp.settledOrder }); assert.equal(v.effective.sourceClockStatus, SOCIAL_VIEW_CONFLICT_STATE); assert.equal(v.effective.clockIntegrity, 'LEGACY_UNSEALED');
  const before = socialTemporalView({ event: target, annotations: cp.annotations.get(id), pending: cp.pendingByTarget.get(id), asOfTs: REC.T1, settledOrder: cp.settledOrder }); assert.equal(before.effective.sourceDeclaredTs, T_MS + 100); assert.equal(before.effective.clockIntegrity, 'LEGACY_UNSEALED');
  // a legacy record whose links cannot be verified against actual history: retained, reported, never applied
  const legacyPending = pend(conflict.history)[0]; assert.equal(legacyPending.schemaVersion, 1);
  const other = asEvent(obs('bsky', bsky(T_Z, { seq: 77, rkey: 'k77', cid: 'bafy77' }), T0)); const retargeted = { ...structuredClone(legacyPending), candidateIds: [other.sourceEventId] };
  assert.equal(validateSocialReconciliationPending(retargeted), null, 'a version-1 identity never bound its target set — this cannot be detected by the record alone (stated limit)');
  const rl = replaySocialHistory([...src(conflict.history), other, ...ann(conflict.history), retargeted]); assert.equal(rl.ok, true, 'legacy bytes are never called corrupt for predating the seal');
  assert.equal(rl.pendingUnlinked.length, 1); assert.match(rl.pendingUnlinked[0].reason, /not the same native occurrence/); assert.equal(rl.pendingByTarget.has(other.sourceEventId), false); assert.equal(rl.pendingIds.has(retargeted.sourceEventId), true, 'retained as an unresolved observation');
  assert.equal(socialTemporalView({ event: other, asOfTs: REC.T2 }).conflict, null); assert.match(socialTemporalView({ event: other, pending: [retargeted], asOfTs: REC.T2 }).error, /context invalid/);
  // a legacy pending record with backdated clocks cannot be detected by the record alone either: stated limit, no seal is invented
  const moved = structuredClone(legacyPending); moved.knownAtTs = REC.T0 + 1; moved.ts = new Date(REC.T0 + 1).toISOString(); moved.candidate.retrievedTs = REC.T0 + 1; assert.equal(validateSocialReconciliationPending(moved), null);
  // the candidate keeps-first over the legacy identity for the same target set (no duplicate sealed twin)
  const r = rec(conflict.history); const again = r.reconcile(obs('bsky', bsky('2026-09-06T12:00:00.200Z'), REC.T2 + 1), r.batch({ knownAtTs: REC.T2 + 1 })); assert.equal(again.kind, 'KNOWN'); assert.equal(again.legacyRecord, true);
});

